def count_chaotic_merges(x, y):
    n, m = len(x), len(y)

    # dp[i][j] will store the number of ways to merge x[:i] and y[:j] into a chaotic string
    dp = [[0] * (m + 1) for _ in range(n + 1)]

    # Base case: empty strings can be merged into an empty chaotic string in one way
    dp[0][0] = 1

    # Fill the dp table
    for i in range(n + 1):
        for j in range(m + 1):
            if i > 0:
                dp[i][j] += dp[i - 1][j]
                if j > 0 and x[i - 1] != y[j - 1]:
                    dp[i][j] += dp[i - 1][j - 1]
            if j > 0:
                dp[i][j] += dp[i][j - 1]
                if i > 0 and x[i - 1] != y[j - 1]:
                    dp[i][j] += dp[i - 1][j - 1]
            dp[i][j] %= MOD

    # Calculate the result
    result = 0
    for i in range(1, n + 1):
        for j in range(1, m + 1):
            for k in range(i):
                for l in range(j):
                    if x[k] != y[l]:
                        result += dp[k][l]
                        result %= MOD

    return result

